css:
.dcx{ -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
.dcx{ margin: 0; background: #F7F8F5; color: #08120D; font-family: 'Instrument Sans', system-ui, sans-serif; -webkit-font-smoothing: antialiased; overflow-x:clip; }
.dcx *{ box-sizing: border-box; }
.dcx h1,.dcx h2,.dcx h3,.dcx h4{ margin: 0; font-family: 'Bricolage Grotesque', system-ui, sans-serif; font-weight: 700; letter-spacing: -0.025em; text-wrap: balance; }
.dcx p{ margin: 0; text-wrap: pretty; }
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx ::selection{ background: #16A85F; color: #fff; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; border-radius: 4px; }
.dcx section{ overflow-x: clip; }
@keyframes nxPulse{ 0%,100% { opacity: .35; transform: scale(1); } 50% { opacity: .9; transform: scale(1.35); } }
@keyframes nxFloat{ 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
@keyframes nxDash{ to { stroke-dashoffset: -240; } }
@keyframes nxSpin{ to { transform: rotate(360deg); } }
.dcx [data-nav-toggle]{ display: none; }
@media (max-width: 1280px){.dcx [data-split]{ grid-template-columns: minmax(0, 1fr) !important; }
}
@media (max-width: 1024px){.dcx [data-nav]{ gap: 16px !important; padding: 0 20px !important; }
.dcx [data-nav-links],.dcx [data-nav-lang],.dcx [data-nav-login]{ display: none !important; }
.dcx [data-nav-toggle]{ display: grid !important; }
.dcx [data-nav-sheet][data-open="1"]{ display: block !important; }
}
@media (max-width: 900px){.dcx [data-dash-side]{ display: none !important; }
.dcx [data-dash]{ grid-template-columns: minmax(0, 1fr) !important; }
.dcx [data-dash-kpi]{ grid-template-columns: repeat(auto-fit, minmax(132px, 1fr)) !important; }
}
@media (max-width: 760px){.dcx section{ padding-left: 20px !important; padding-right: 20px !important; }
.dcx footer{ padding-left: 20px !important; padding-right: 20px !important; }
.dcx h1{ font-size: 40px !important; }
.dcx h2{ font-size: 30px !important; }
}
@media (prefers-reduced-motion: reduce){.dcx *{ animation: none !important; transition: none !important; }
}
.dcx ::-webkit-scrollbar{ height: 8px; width: 8px; }
.dcx ::-webkit-scrollbar-thumb{ background: rgba(11,107,63,.25); border-radius: 8px; }
